extern const LoomGeneratedCollisionCellRecord loom_generated_collision_cells[LOOM_GENERATED_COLLISION_CELL_STORAGE_COUNT];
extern const LoomGeneratedEntityRecord loom_generated_entities[LOOM_GENERATED_ENTITY_STORAGE_COUNT];
extern const LoomGeneratedComponentRecord loom_generated_components[LOOM_GENERATED_COMPONENT_STORAGE_COUNT];
extern const LoomGeneratedWorldRecord loom_generated_worlds[LOOM_GENERATED_WORLD_STORAGE_COUNT];
